import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { useForm } from 'react-hook-form';
import { motion } from 'framer-motion';
import { FiEye, FiEyeOff, FiMail, FiLock, FiPhone, FiUser, FiCalendar, FiUserCheck } from 'react-icons/fi';
import { registerUser, sendOTP, verifyOTP, clearError, setRegistrationStep } from '../../store/slices/authSlice';
import LoadingSpinner from '../../components/UI/LoadingSpinner';

const Register = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isLoading, error, isAuthenticated, registrationStep, otpSent, otpVerified } = useSelector((state) => state.auth);
  
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [userType, setUserType] = useState('patient');
  const [otpData, setOtpData] = useState({ email: '', mobile: '' });

  const {
    register,
    handleSubmit,
    formState: { errors },
    watch,
    setValue,
    getValues,
  } = useForm();

  useEffect(() => {
    if (isAuthenticated) {
      navigate('/dashboard');
    }
  }, [isAuthenticated, navigate]);

  useEffect(() => {
    dispatch(clearError());
  }, [dispatch]);

  const password = watch('password');

  const onSubmit = (data) => {
    // Direct registration without OTP
    const userData = {
      ...data,
      userType,
      dateOfBirth: new Date(data.dateOfBirth).toISOString(),
    };
    dispatch(registerUser(userData));
  };

  const resendOTP = (type) => {
    const identifier = type === 'email' ? otpData.email : otpData.mobile;
    dispatch(sendOTP({
      identifier,
      type,
      purpose: type === 'email' ? 'email-verification' : 'mobile-verification'
    }));
  };

  const goBack = () => {
    if (registrationStep > 1) {
      dispatch(setRegistrationStep(registrationStep - 1));
    }
  };

  return (
    <div className="min-h-screen gradient-bg flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="max-w-md w-full space-y-8"
      >
        {/* Header */}
        <div className="text-center">
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
            className="mx-auto h-16 w-16 bg-gradient-to-r from-primary-600 to-health-600 rounded-full flex items-center justify-center"
          >
            <span className="text-2xl font-bold text-white">HC</span>
          </motion.div>
          <h2 className="mt-6 text-3xl font-bold text-gray-900">
            {registrationStep === 1 ? 'Create your account' : 'Verify your account'}
          </h2>
          <p className="mt-2 text-sm text-gray-600">
            {registrationStep === 1 
              ? 'Join Health Chat and connect with healthcare professionals'
              : 'We sent verification codes to your email and mobile'
            }
          </p>
        </div>

        {/* Registration Form */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="bg-white py-8 px-6 shadow-xl rounded-2xl"
        >
          {/* Progress Indicator */}
          <div className="mb-6">
            <div className="flex items-center justify-between">
              <div className={`flex items-center ${registrationStep >= 1 ? 'text-primary-600' : 'text-gray-400'}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                  registrationStep >= 1 ? 'bg-primary-600 text-white' : 'bg-gray-200'
                }`}>
                  1
                </div>
                <span className="ml-2 text-sm font-medium">Basic Info</span>
              </div>
              <div className={`flex-1 h-1 mx-4 ${registrationStep >= 2 ? 'bg-primary-600' : 'bg-gray-200'}`}></div>
              <div className={`flex items-center ${registrationStep >= 2 ? 'text-primary-600' : 'text-gray-400'}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                  registrationStep >= 2 ? 'bg-primary-600 text-white' : 'bg-gray-200'
                }`}>
                  2
                </div>
                <span className="ml-2 text-sm font-medium">Verify</span>
              </div>
            </div>
          </div>

          <form className="space-y-6" onSubmit={handleSubmit(onSubmit)}>
            {registrationStep === 1 ? (
              <>
                {/* User Type Selection */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-3">
                    I am a
                  </label>
                  <div className="grid grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => setUserType('patient')}
                      className={`p-3 rounded-lg border-2 text-center transition-colors ${
                        userType === 'patient'
                          ? 'border-primary-600 bg-primary-50 text-primary-700'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <FiUser className="mx-auto h-6 w-6 mb-1" />
                      <div className="text-sm font-medium">Patient</div>
                    </button>
                    <button
                      type="button"
                      onClick={() => setUserType('doctor')}
                      className={`p-3 rounded-lg border-2 text-center transition-colors ${
                        userType === 'doctor'
                          ? 'border-primary-600 bg-primary-50 text-primary-700'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <FiUserCheck className="mx-auto h-6 w-6 mb-1" />
                      <div className="text-sm font-medium">Doctor</div>
                    </button>
                  </div>
                </div>

                {/* Full Name */}
                <div>
                  <label htmlFor="fullName" className="block text-sm font-medium text-gray-700 mb-2">
                    Full Name
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiUser className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('fullName', {
                        required: 'Full name is required',
                        minLength: {
                          value: 2,
                          message: 'Name must be at least 2 characters'
                        }
                      })}
                      type="text"
                      className={`input-field pl-10 ${errors.fullName ? 'input-error' : ''}`}
                      placeholder="Enter your full name"
                    />
                  </div>
                  {errors.fullName && (
                    <p className="mt-1 text-sm text-red-600">{errors.fullName.message}</p>
                  )}
                </div>

                {/* Email */}
                <div>
                  <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                    Email Address
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiMail className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('email', {
                        required: 'Email is required',
                        pattern: {
                          value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                          message: 'Invalid email address'
                        }
                      })}
                      type="email"
                      className={`input-field pl-10 ${errors.email ? 'input-error' : ''}`}
                      placeholder="Enter your email"
                    />
                  </div>
                  {errors.email && (
                    <p className="mt-1 text-sm text-red-600">{errors.email.message}</p>
                  )}
                </div>

                {/* Mobile */}
                <div>
                  <label htmlFor="mobile" className="block text-sm font-medium text-gray-700 mb-2">
                    Mobile Number
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiPhone className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('mobile', {
                        required: 'Mobile number is required',
                        pattern: {
                          value: /^[\+]?[1-9][\d]{0,15}$/,
                          message: 'Invalid mobile number'
                        }
                      })}
                      type="tel"
                      className={`input-field pl-10 ${errors.mobile ? 'input-error' : ''}`}
                      placeholder="Enter your mobile number"
                    />
                  </div>
                  {errors.mobile && (
                    <p className="mt-1 text-sm text-red-600">{errors.mobile.message}</p>
                  )}
                </div>

                {/* Date of Birth */}
                <div>
                  <label htmlFor="dateOfBirth" className="block text-sm font-medium text-gray-700 mb-2">
                    Date of Birth
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiCalendar className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('dateOfBirth', {
                        required: 'Date of birth is required'
                      })}
                      type="date"
                      className={`input-field pl-10 ${errors.dateOfBirth ? 'input-error' : ''}`}
                    />
                  </div>
                  {errors.dateOfBirth && (
                    <p className="mt-1 text-sm text-red-600">{errors.dateOfBirth.message}</p>
                  )}
                </div>

                {/* Gender */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Gender
                  </label>
                  <select
                    {...register('gender', {
                      required: 'Gender is required'
                    })}
                    className={`input-field ${errors.gender ? 'input-error' : ''}`}
                  >
                    <option value="">Select gender</option>
                    <option value="male">Male</option>
                    <option value="female">Female</option>
                    <option value="other">Other</option>
                  </select>
                  {errors.gender && (
                    <p className="mt-1 text-sm text-red-600">{errors.gender.message}</p>
                  )}
                </div>

                {/* Doctor-specific fields */}
                {userType === 'doctor' && (
                  <>
                    <div>
                      <label htmlFor="specialization" className="block text-sm font-medium text-gray-700 mb-2">
                        Specialization
                      </label>
                      <input
                        {...register('specialization', {
                          required: userType === 'doctor' ? 'Specialization is required' : false
                        })}
                        type="text"
                        className={`input-field ${errors.specialization ? 'input-error' : ''}`}
                        placeholder="e.g., Cardiology, Dermatology"
                      />
                      {errors.specialization && (
                        <p className="mt-1 text-sm text-red-600">{errors.specialization.message}</p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="licenseNumber" className="block text-sm font-medium text-gray-700 mb-2">
                        License Number
                      </label>
                      <input
                        {...register('licenseNumber', {
                          required: userType === 'doctor' ? 'License number is required' : false
                        })}
                        type="text"
                        className={`input-field ${errors.licenseNumber ? 'input-error' : ''}`}
                        placeholder="Enter your medical license number"
                      />
                      {errors.licenseNumber && (
                        <p className="mt-1 text-sm text-red-600">{errors.licenseNumber.message}</p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="experience" className="block text-sm font-medium text-gray-700 mb-2">
                        Years of Experience
                      </label>
                      <input
                        {...register('experience', {
                          required: userType === 'doctor' ? 'Experience is required' : false,
                          min: { value: 0, message: 'Experience must be 0 or more' },
                          max: { value: 50, message: 'Experience must be 50 or less' }
                        })}
                        type="number"
                        min="0"
                        max="50"
                        className={`input-field ${errors.experience ? 'input-error' : ''}`}
                        placeholder="0"
                      />
                      {errors.experience && (
                        <p className="mt-1 text-sm text-red-600">{errors.experience.message}</p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="consultationFee" className="block text-sm font-medium text-gray-700 mb-2">
                        Consultation Fee (₹)
                      </label>
                      <input
                        {...register('consultationFee', {
                          required: userType === 'doctor' ? 'Consultation fee is required' : false,
                          min: { value: 0, message: 'Fee must be 0 or more' }
                        })}
                        type="number"
                        min="0"
                        className={`input-field ${errors.consultationFee ? 'input-error' : ''}`}
                        placeholder="500"
                      />
                      {errors.consultationFee && (
                        <p className="mt-1 text-sm text-red-600">{errors.consultationFee.message}</p>
                      )}
                    </div>
                  </>
                )}

                {/* Password */}
                <div>
                  <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-2">
                    Password
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiLock className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('password', {
                        required: 'Password is required',
                        minLength: {
                          value: 6,
                          message: 'Password must be at least 6 characters'
                        }
                      })}
                      type={showPassword ? 'text' : 'password'}
                      className={`input-field pl-10 pr-10 ${errors.password ? 'input-error' : ''}`}
                      placeholder="Create a password"
                    />
                    <button
                      type="button"
                      className="absolute inset-y-0 right-0 pr-3 flex items-center"
                      onClick={() => setShowPassword(!showPassword)}
                    >
                      {showPassword ? (
                        <FiEyeOff className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                      ) : (
                        <FiEye className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                      )}
                    </button>
                  </div>
                  {errors.password && (
                    <p className="mt-1 text-sm text-red-600">{errors.password.message}</p>
                  )}
                </div>

                {/* Confirm Password */}
                <div>
                  <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-700 mb-2">
                    Confirm Password
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <FiLock className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                      {...register('confirmPassword', {
                        required: 'Please confirm your password',
                        validate: value => value === password || 'Passwords do not match'
                      })}
                      type={showConfirmPassword ? 'text' : 'password'}
                      className={`input-field pl-10 pr-10 ${errors.confirmPassword ? 'input-error' : ''}`}
                      placeholder="Confirm your password"
                    />
                    <button
                      type="button"
                      className="absolute inset-y-0 right-0 pr-3 flex items-center"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    >
                      {showConfirmPassword ? (
                        <FiEyeOff className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                      ) : (
                        <FiEye className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                      )}
                    </button>
                  </div>
                  {errors.confirmPassword && (
                    <p className="mt-1 text-sm text-red-600">{errors.confirmPassword.message}</p>
                  )}
                </div>
              </>
            ) : (
              <>
                {/* OTP Verification */}
                <div className="space-y-4">
                  <div className="text-center">
                    <p className="text-sm text-gray-600 mb-4">
                      We sent verification codes to:
                    </p>
                    <div className="space-y-2">
                      <p className="text-sm font-medium text-gray-900">{otpData.email}</p>
                      <p className="text-sm font-medium text-gray-900">{otpData.mobile}</p>
                    </div>
                  </div>

                  <div>
                    <label htmlFor="emailOtp" className="block text-sm font-medium text-gray-700 mb-2">
                      Email Verification Code
                    </label>
                    <input
                      {...register('emailOtp', {
                        required: 'Email OTP is required',
                        pattern: {
                          value: /^\d{6}$/,
                          message: 'OTP must be 6 digits'
                        }
                      })}
                      type="text"
                      maxLength="6"
                      className={`input-field text-center text-lg tracking-widest ${errors.emailOtp ? 'input-error' : ''}`}
                      placeholder="000000"
                    />
                    {errors.emailOtp && (
                      <p className="mt-1 text-sm text-red-600">{errors.emailOtp.message}</p>
                    )}
                    <div className="flex justify-between mt-2">
                      <button
                        type="button"
                        onClick={() => resendOTP('email')}
                        className="text-sm text-primary-600 hover:text-primary-500"
                      >
                        Resend Email OTP
                      </button>
                      {process.env.NODE_ENV === 'development' && (
                        <button
                          type="button"
                          onClick={() => {
                            setValue('emailOtp', '123456');
                            setValue('mobileOtp', '123456');
                          }}
                          className="text-sm text-green-600 hover:text-green-500"
                        >
                          Use Test OTP (123456)
                        </button>
                      )}
                    </div>
                  </div>

                  <div>
                    <label htmlFor="mobileOtp" className="block text-sm font-medium text-gray-700 mb-2">
                      Mobile Verification Code
                    </label>
                    <input
                      {...register('mobileOtp', {
                        required: 'Mobile OTP is required',
                        pattern: {
                          value: /^\d{6}$/,
                          message: 'OTP must be 6 digits'
                        }
                      })}
                      type="text"
                      maxLength="6"
                      className={`input-field text-center text-lg tracking-widest ${errors.mobileOtp ? 'input-error' : ''}`}
                      placeholder="000000"
                    />
                    {errors.mobileOtp && (
                      <p className="mt-1 text-sm text-red-600">{errors.mobileOtp.message}</p>
                    )}
                    <button
                      type="button"
                      onClick={() => resendOTP('mobile')}
                      className="mt-2 text-sm text-primary-600 hover:text-primary-500"
                    >
                      Resend SMS OTP
                    </button>
                  </div>
                </div>
              </>
            )}

            {/* Error Message */}
            {error && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-red-50 border border-red-200 rounded-lg p-3"
              >
                <p className="text-sm text-red-600">{error}</p>
              </motion.div>
            )}

            {/* Submit Button */}
            <div className="flex space-x-3">
              {registrationStep > 1 && (
                <button
                  type="button"
                  onClick={goBack}
                  className="flex-1 btn-secondary"
                >
                  Back
                </button>
              )}
              <button
                type="submit"
                disabled={isLoading}
                className={`${registrationStep > 1 ? 'flex-1' : 'w-full'} btn-primary flex items-center justify-center py-3 text-base font-medium disabled:opacity-50 disabled:cursor-not-allowed`}
              >
                {isLoading ? (
                  <LoadingSpinner size="small" />
                ) : (
                  registrationStep === 1 ? 'Create Account' : 'Verify & Complete'
                )}
              </button>
            </div>
          </form>

          {/* Sign In Link */}
          <div className="mt-6 text-center">
            <p className="text-sm text-gray-600">
              Already have an account?{' '}
              <Link
                to="/login"
                className="font-medium text-primary-600 hover:text-primary-500 transition-colors"
              >
                Sign in here
              </Link>
            </p>
          </div>
        </motion.div>

        {/* Footer */}
        <div className="text-center text-sm text-gray-500">
          <p>© 2024 Health Chat. All rights reserved.</p>
        </div>
      </motion.div>
    </div>
  );
};

export default Register;
